"""
    Returns `lst[ind]` if it exists, `default` otherwise.

        >>> listget(['a'], 0)
        'a'
        >>> listget(['a'], 1)
        >>> listget(['a'], 1, 'b')
        'b'
    """
def listget(lst: Any, ind: Any, `default: Any = None) -> object {
    if ((len(lst) - 1) < ind) {
        return `default;
    }
    return lst[ind];
}

